<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { onShow, onPullDownRefresh } from '@dcloudio/uni-app';
import { useI18n } from 'vue-i18n';
import { useMerchantStore } from '@/stores/merchant';
import { USE_MOCK } from '@/api';
import { callPrint, PrintCommands, operationResult, decodeFrozen, type FrozenJson, type PrintPage, type Scene, type Printer, type PrintTemplate, type TemplateContent, type ScenePolicy, type Route } from '@/api/print';
import { receiptPreviewLines, type ReceiptPreviewData } from '@/shared/print-center';
const {t}=useI18n(), merchant=useMerchantStore(), commands=new PrintCommands();
const scenes=ref<Scene[]>([]), printers=ref<Printer[]>([]), templates=ref<PrintTemplate[]>([]), policies=ref<ScenePolicy[]>([]), routes=ref<Route[]>([]);
const scene=ref('ORDER_PAID'), width=ref(80), footer=ref(''), error=ref(''), busy=ref(false), enabled=ref(false), copies=ref('1'), selectedPrinters=ref<string[]>([]), previewLines=ref<string[]>([]);
const baseTemplate=ref<TemplateContent|null>(null), mandatory=ref<string[]>([]), hidden=ref<string[]>([]);
let epoch=0;
const selectedScene=computed(()=>scenes.value.find(s=>s.scene===scene.value));
const eligiblePrinters=computed(()=>printers.value.filter(p=>p.paperWidthMm===width.value&&p.status==='ACTIVE'));
const fieldOptions=computed(()=>baseTemplate.value?.blocks.filter(b=>b.binding&&b.type==='keyValue').map(b=>({path:String(b.binding),label:String(b.label||b.binding),required:mandatory.value.includes(String(b.binding))}))||[]);
function fail(e:unknown){error.value=e instanceof Error?e.message:String(t('printCenter.failed'));}
async function load(){if(USE_MOCK)return;await merchant.ensureScope();const version=++epoch,storeNo=merchant.storeNo;try{const [all,p,pol,rt]=await Promise.all([callPrint<Scene[]>('C01',{storeNo}),callPrint<PrintPage<Printer>>('P02',{storeNo,page:1,size:100}),callPrint<ScenePolicy[]>('C02',{storeNo}),callPrint<PrintPage<Route>>('C12',{storeNo,scene:scene.value,page:1,size:100})]);if(version!==epoch||storeNo!==merchant.storeNo)return;scenes.value=all;printers.value=p.records;policies.value=pol;routes.value=rt.records;enabled.value=pol.find(s=>s.scene===scene.value)?.enabled||false;await loadTemplate();}catch(e){fail(e);}}
async function loadTemplate(){const version=++epoch,storeNo=merchant.storeNo;try{const variantCode='STANDARD_'+width.value;const [example,fields,list]=await Promise.all([callPrint<{baseTemplate:FrozenJson}>('C20',{storeNo,variantCode},{scene:scene.value}),callPrint<{catalog:FrozenJson}>('C19',{storeNo,payloadSchemaVersion:1},{scene:scene.value}),callPrint<PrintPage<PrintTemplate>>('C05',{storeNo,scene:scene.value,variantCode,page:1,size:100})]);if(version!==epoch||storeNo!==merchant.storeNo)return;baseTemplate.value=decodeFrozen<TemplateContent>(example.baseTemplate);mandatory.value=decodeFrozen<{mandatoryPrintPaths:string[]}>(fields.catalog).mandatoryPrintPaths;templates.value=list.records;previewLines.value=[];hidden.value=[];selectedPrinters.value=[];}catch(e){fail(e);}}
function selectScene(e:{detail:{value:string|number}}){scene.value=scenes.value[Number(e.detail.value)]?.scene||'ORDER_PAID';enabled.value=policies.value.find(p=>p.scene===scene.value)?.enabled||false;void load();}
function toggleField(path:string){if(mandatory.value.includes(path))return;hidden.value=hidden.value.includes(path)?hidden.value.filter(x=>x!==path):[...hidden.value,path];}
function togglePrinter(no:string){selectedPrinters.value=selectedPrinters.value.includes(no)?selectedPrinters.value.filter(x=>x!==no):[...selectedPrinters.value,no];}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(e){fail(e);}finally{busy.value=false;}}
async function saveTemplate(publish:boolean){await run(async()=>{if(!baseTemplate.value)throw new Error(String(t('printCenter.templateMissing')));let head=templates.value.find(x=>x.scopeKey==='STORE:'+merchant.storeNo);if(!head){const op=await commands.run('C06',{storeNo:merchant.storeNo,scene:scene.value,variantCode:'STANDARD_'+width.value,name:selectedScene.value?.title||scene.value});const no=operationResult<{templateNo:string}>(op).templateNo;head={templateNo:no,scene:scene.value,variantCode:'STANDARD_'+width.value,name:selectedScene.value?.title||scene.value,currentVersionNo:null,revision:0,scopeKey:'STORE:'+merchant.storeNo};templates.value=[head,...templates.value];}
 const content:TemplateContent=JSON.parse(JSON.stringify(baseTemplate.value)) as TemplateContent;content.blocks=content.blocks.filter(b=>!b.binding||!hidden.value.includes(b.binding));if(footer.value.trim())content.blocks.push({type:'text',literal:footer.value.trim()});
 const created=await commands.run('C07',{expectedRevision:head.revision,format:'PRINT_DOC_V1',schemaVersion:1,payloadSchemaVersion:1,paperWidthMm:width.value,content,compatibleCapabilities:[]},{templateNo:head.templateNo});const versionNo=operationResult<{templateVersionNo:string}>(created).templateVersionNo;head.revision++;
 const preview=await callPrint<{document:{businessData:FrozenJson;systemSlots:{warnings:string[]}}}>('C09',{sampleSourceRef:null,paperWidthMm:width.value},{versionNo});previewLines.value=receiptPreviewLines(decodeFrozen<ReceiptPreviewData>(preview.document.businessData),preview.document.systemSlots.warnings);
 if(publish){await commands.run('C10',{expectedRevision:0,expectedTemplateRevision:head.revision},{versionNo});head.currentVersionNo=versionNo;head.revision++;}
 });}
async function saveRoute(){await run(async()=>{const quantity=Number(copies.value);if(!Number.isInteger(quantity)||quantity<1||quantity>10||!selectedPrinters.value.length)throw new Error(String(t('printCenter.routeSelectionRequired')));let head=routes.value.find(r=>r.scene===scene.value);if(!head){const op=await commands.run('C13',{storeNo:merchant.storeNo,scene:scene.value});head={routeNo:operationResult<{routeNo:string}>(op).routeNo,scene:scene.value,currentVersionNo:null,revision:0};routes.value=[head];}const created=await commands.run('C14',{expectedRevision:head.revision,rules:[{ruleKey:'DEFAULT',priority:0,match:{all:[]},targets:selectedPrinters.value.map((no,index)=>({targetKey:'T'+(index+1),printerNo:no,copies:quantity,required:true,templateSelection:{mode:'SCENE_DEFAULT',variantCode:'STANDARD_'+width.value,templateVersionNo:null}}))}]},{routeNo:head.routeNo});const versionNo=operationResult<{routeVersionNo:string}>(created).routeVersionNo;head.revision++;await commands.run('C16',{expectedRevision:0,expectedRouteRevision:head.revision},{versionNo});head.currentVersionNo=versionNo;head.revision++;});}
async function savePolicy(){await run(async()=>{const existing=policies.value.find(p=>p.scene===scene.value);await commands.run('C03',{storeNo:merchant.storeNo,expectedRevision:existing?.revision||0,policy:{enabled:enabled.value,critical:false,triggerTypes:selectedScene.value?.triggers||['ORDER_PAYMENT_CONFIRMED'],fallbackPrinterNo:null,submitTimeoutSeconds:15,resultTimeoutSeconds:120,maxRetryCount:5,backlogAlertSeconds:60,staleAfterSeconds:600,notificationPolicy:{onBatchResolved:true,onIncident:true,recipientRoleKeys:['STORE_MANAGER'],channels:['IN_APP']},outputOptions:{pdfEnabled:true,pdfProfile:'ORIGINAL_ROLL'}}},{scene:scene.value});await load();});}
watch(width,()=>{void loadTemplate();});watch(()=>merchant.storeNo,()=>{epoch++;baseTemplate.value=null;previewLines.value=[];commands.clear();void load();});
onShow(()=>{void load();});onPullDownRefresh(async()=>{await load();uni.stopPullDownRefresh();});
function changeEnabled(event: Event) { enabled.value = Boolean((event as unknown as { detail: { value: boolean } }).detail.value); }
</script>
<template>
 <sh-scaffold title-key="printCenter.templates" :denied="!merchant.can('biz:print:config')">
  <view v-if="USE_MOCK" class="sh-card">{{ t('printCenter.mockHint') }}</view>
  <template v-else>
   <view v-if="error" class="sh-card print-error" role="alert">{{ error }}</view>
   <view class="sh-card"><picker :range="scenes.map(s=>s.title)" @change="selectScene"><view class="sh-cell">{{ selectedScene?.title||scene }} ▾</view></picker><view class="sh-row"><button size="mini" :class="width===58?'print-selected':''" @tap="width=58">58mm</button><button size="mini" :class="width===80?'print-selected':''" @tap="width=80">80mm</button></view><text v-if="!selectedScene?.sourceAvailable" class="print-hint">{{ t('printCenter.sourceUnavailable') }}</text></view>
   <view class="sh-card"><text class="txt-strong">{{ t('printCenter.receiptFields') }}</text><text class="print-hint">{{ t('printCenter.requiredFieldsHint') }}</text><view v-for="field in fieldOptions" :key="field.path" class="sh-cell sh-row sh-row--between" @tap="toggleField(field.path)"><text>{{ field.label }}{{ field.required?' · '+t('printCenter.required'):'' }}</text><text>{{ hidden.includes(field.path)?'□':'✓' }}</text></view><input v-model="footer" :placeholder="String(t('printCenter.footer'))" :maxlength="120" /><view class="sh-row"><button size="mini" :disabled="busy||!baseTemplate" @tap="saveTemplate(false)">{{ t('printCenter.savePreview') }}</button><button size="mini" :disabled="busy||!baseTemplate" @tap="saveTemplate(true)">{{ t('printCenter.publishTemplate') }}</button></view></view>
   <view v-if="previewLines.length" class="sh-card print-receipt"><text v-for="(line,index) in previewLines" :key="index" selectable>{{ line }}</text></view>
   <view class="sh-card"><text class="txt-strong">{{ t('printCenter.route') }}</text><text class="print-hint">{{ t('printCenter.routeHint') }}</text><view v-for="printer in eligiblePrinters" :key="printer.printerNo" class="sh-cell sh-row sh-row--between" @tap="togglePrinter(printer.printerNo)"><text>{{ printer.name }}</text><text>{{ selectedPrinters.includes(printer.printerNo)?'✓':'□' }}</text></view><input v-model="copies" type="number" :placeholder="String(t('printCenter.copies'))" /><button :disabled="busy||!selectedPrinters.length" @tap="saveRoute">{{ t('printCenter.publishRoute') }}</button></view>
   <view class="sh-card"><view class="sh-row sh-row--between"><text>{{ t('printCenter.autoPrint') }}</text><switch :checked="enabled" :disabled="!selectedScene?.sourceAvailable" @change="changeEnabled" /></view><text class="print-hint">{{ t('printCenter.policyHint') }}</text><button :disabled="busy" @tap="savePolicy">{{ t('printCenter.savePolicy') }}</button></view>
  </template>
 </sh-scaffold>
</template>
<style scoped>
input{padding:20rpx 0;border-bottom:1px solid var(--sh-border,#eee)}.print-hint{display:block;font-size:24rpx;color:var(--sh-text-secondary,#666);margin:12rpx 0}.print-receipt text{display:block;white-space:pre-wrap;overflow-wrap:anywhere;font-size:24rpx}.print-error{color:var(--sh-danger,#c0392b)}
</style>

<style scoped>.print-selected{background:#1677ff;color:white;}</style>
